{"revision":"8f4de8526bc2b4a043cfb493c180709292ed245bbf97bef8b7e9e4b4891a76a5","id":"mcp.tool.add_workitem","version":1,"transportName":"add_workitem","description":"Create Planning task: item requires id,title,goal,scope,acceptance; optional
